<script setup>
import { ref, onMounted, onUnmounted, computed } from 'vue'
import { BookOpen, LayoutDashboard, FileText, Users, MessagesSquare, MessageSquare, LogOut, ArrowRight, ArrowUpRight, ShieldCheck, Menu, X, ChevronDown, CircleHelp } from 'lucide-vue-next'
import { api } from './api'
import Chat from './Chat.vue'
import Admin from './Admin.vue'
const user = ref(null), health = ref({ mode: 'demo' }), page = ref('chat'), loginError = ref(''), bootError = ref(''), loginBusy = ref(false), initializing = ref(true), mobileNav = ref(false)
const username = ref('operator'), password = ref(''), initialConversation = new URLSearchParams(location.search).get('conversation') || ''
const nav = computed(() => user.value?.role === 'admin' ? [ { id: 'overview', title: '工作台概览', icon: LayoutDashboard }, { id: 'chat', title: '知识助手', icon: MessageSquare }, { id: 'documents', title: '知识文档', icon: FileText }, { id: 'users', title: '员工管理', icon: Users }, { id: 'runs', title: '问答与反馈', icon: MessagesSquare } ] : [{ id: 'chat', title: '知识助手', icon: MessageSquare }, { id: 'library', title: '知识文库', icon: BookOpen }])
const library = ref([]), librarySearch = ref(''), libraryDoc = ref(null), libraryError = ref('')
import Markdown from './Markdown.vue'
const libraryFiltered = computed(() => library.value.filter(x => `${x.title} ${x.code} ${x.category}`.includes(librarySearch.value)))
async function navigate(id) { page.value = id; mobileNav.value = false; location.hash = id; if (id === 'library') { try { library.value = await api('/documents') } catch (e) { libraryError.value = e.message } } }
async function viewDoc(d) { try { libraryDoc.value = await api(`/documents/${d.id}`) } catch (e) { libraryError.value = e.message } }
async function login() { loginBusy.value = true; loginError.value = ''; try { const data = await api('/auth/login', { method: 'POST', body: { username: username.value, password: password.value } }); sessionStorage.setItem('zhixu_token', data.token); user.value = data.user; password.value = ''; navigate(user.value.role === 'admin' ? 'overview' : 'chat') } catch (e) { loginError.value = e.message } finally { loginBusy.value = false } }
function logout() { sessionStorage.removeItem('zhixu_token'); user.value = null; password.value = ''; page.value = 'chat'; location.hash = '' }
function expired() { logout(); loginError.value = '登录已失效，请重新登录' }
function hashChanged() { const p = location.hash.slice(1); if (nav.value.some(n => n.id === p)) navigate(p) }
onMounted(async () => { window.addEventListener('session-expired', expired); window.addEventListener('hashchange', hashChanged); try { health.value = await api('/health'); if (sessionStorage.getItem('zhixu_token')) { user.value = await api('/auth/me'); const p = location.hash.slice(1); navigate(nav.value.some(n => n.id === p) ? p : user.value.role === 'admin' ? 'overview' : 'chat') } } catch (e) { bootError.value = e.message } finally { initializing.value = false } })
onUnmounted(() => { window.removeEventListener('session-expired', expired); window.removeEventListener('hashchange', hashChanged) })
</script>
<template>
  <div v-if="initializing" class="boot-screen"><div class="brand-mark"><BookOpen :size="25"/></div><p>正在打开知序工作台…</p></div>
  <div v-else-if="!user" class="login-layout"><section class="login-story"><a href="#" class="brand"><div class="brand-mark"><BookOpen :size="23" :stroke-width="1.7"/></div><strong>知序<span>ZHIXU</span></strong></a><div class="login-copy"><span class="eyebrow">A GOOD START BEGINS WITH KNOWLEDGE</span><h1>每一个新开始，<br/>都有据可循。</h1><p>把公司知识变成随时可用的答案。<br/>让了解更轻松，让协作更从容。</p><div class="login-paper"><span class="paper-tag">YOUR FIRST WEEK</span><div><span>01</span>认识业务，找到方向<ShieldCheck :size="18"/></div><div><span>02</span>理解职责，连接团队<ShieldCheck :size="18"/></div><div><span>03</span>查阅流程，安心上手<ArrowUpRight :size="18"/></div><span class="paper-foot">不止找到答案，更找到答案的依据。</span></div></div><footer>星澜电商 · 员工知识工作台<span>模拟企业 / 求职演示项目</span></footer></section><main class="login-form-side"><div class="login-form-wrap"><span class="eyebrow">WELCOME TO YOUR WORKSPACE</span><h2>欢迎来到知序</h2><p>登录，开始了解你的新角色。</p><form @submit.prevent="login"><label for="username">员工账号</label><input id="username" v-model="username" autocomplete="username" required placeholder="输入员工账号"/><label for="password">登录密码</label><input id="password" v-model="password" type="password" autocomplete="current-password" required placeholder="输入登录密码"/><p v-if="loginError || bootError" class="error" role="alert">{{ loginError || bootError }}</p><button class="button primary full login-submit" :disabled="loginBusy">{{ loginBusy ? '登录中…' : '进入工作台' }}<ArrowRight :size="18"/></button></form><div v-if="health.mode === 'demo'" class="demo-accounts"><span>本地演示账号</span><div><button type="button" @click="username = 'operator'; password = 'Welcome@2026'">运营员工</button><button type="button" @click="username = 'support'; password = 'Welcome@2026'">客服员工</button><button type="button" @click="username = 'admin'; password = 'Admin@2026'">管理员</button></div><small>如已修改初始密码，请手动输入。</small></div><div class="login-footnote"><ShieldCheck :size="16"/>仅供内部员工使用 · 账号由管理员创建</div></div></main></div>
  <div v-else class="workspace"><div v-if="mobileNav" class="mobile-shade" @click="mobileNav = false"></div><aside class="sidebar" :class="{ 'mobile-open': mobileNav }"><a href="#chat" class="brand" @click.prevent="navigate('chat')"><div class="brand-mark"><BookOpen :size="23" :stroke-width="1.7"/></div><strong>知序<span>ZHIXU</span></strong></a><div class="workspace-switch"><div class="workspace-icon">星</div><div><strong>星澜电商</strong><span>{{ user.role === 'admin' ? '知识管理工作台' : '员工知识工作台' }}</span></div><ChevronDown :size="15"/></div><div class="nav-label">{{ user.role === 'admin' ? '管理空间' : '我的工作空间' }}</div><nav aria-label="主导航"><button v-for="n in nav" :key="n.id" :class="{ active: page === n.id }" @click="navigate(n.id)"><component :is="n.icon" :size="19" :stroke-width="1.7"/><span>{{ n.title }}</span><span v-if="n.id === 'chat'" class="nav-spark">AI</span></button></nav><div class="sidebar-bottom"><div class="sidebar-note"><BookOpen :size="18"/><strong>好问题，值得好答案。</strong><p>从可信文档出发，<br/>让每次追问都有回应。</p></div><div class="mode-indicator"><span class="status-dot"/>{{ health.mode === 'demo' ? '本地演示 · 关键词与原文摘录' : 'API 模式 · RAG 工作流' }}</div><div class="sidebar-user"><div class="avatar small">{{ user.name[0] }}</div><div><strong>{{ user.name }}</strong><span>{{ user.role === 'admin' ? '管理员' : user.position }}</span></div><button class="icon-button" aria-label="退出登录" title="退出登录" @click="logout"><LogOut :size="17"/></button></div></div></aside><main class="main-shell"><div class="mobile-header"><button class="icon-button" aria-label="展开导航" @click="mobileNav = true"><Menu :size="21"/></button><strong>知序 · 星澜电商</strong><button class="icon-button" aria-label="退出登录" @click="logout"><LogOut :size="17"/></button></div><div v-if="health.mode === 'demo'" class="demo-banner"><span class="status-dot"/>演示模式：使用模拟文档、关键词检索与原文摘录。配置 API 后可启用向量检索和模型问答。</div><Chat v-if="page === 'chat'" :user="user" :mode="health.mode" :initial-conversation="initialConversation"/><Admin v-else-if="user.role === 'admin' && page !== 'library'" :page="page" @navigate="navigate"/><section v-else class="admin-page"><header class="page-header"><div><span class="eyebrow">THE COMPANY LIBRARY</span><h1>知识文库</h1><p>了解业务，从一份可信的文档开始。</p></div><span class="pill quiet">{{ library.length }} 个文档版本</span></header><p v-if="libraryError" class="error">{{ libraryError }}</p><div class="table-toolbar"><input v-model="librarySearch" class="library-search" aria-label="搜索知识文库" placeholder="搜索文档名称、分类或编号…"/></div><div class="library-grid"><button v-for="d in libraryFiltered" :key="d.id" class="library-card" @click="viewDoc(d)"><div class="row-between"><span class="mini-file"><FileText :size="21"/></span><span class="pill quiet">{{ d.category }}</span></div><h3>{{ d.title }}</h3><p>{{ d.code }} · v{{ d.version }}</p><div><span>{{ d.effective_from }} 起生效</span><ArrowUpRight :size="17"/></div></button></div><p v-if="!libraryFiltered.length" class="empty-state">没有匹配的已发布文档。</p><div v-if="libraryDoc" class="modal-backdrop" @click.self="libraryDoc = null" @keydown.esc="libraryDoc = null"><article class="modal" role="dialog" aria-modal="true" aria-labelledby="library-title"><header><h2 id="library-title">{{ libraryDoc.title }}</h2><button autofocus class="icon-button" aria-label="关闭文档" @click="libraryDoc = null"><X :size="20"/></button></header><p class="muted">{{ libraryDoc.code }} · v{{ libraryDoc.version }} · {{ libraryDoc.effective_from }} 起生效</p><Markdown :text="libraryDoc.content"/></article></div></section></main></div>
</template>
